    "question": "A cash vault contains Rs. 1, 50 paise, and 25 paise coins in the proportion 2 : 3 : 4. If the cumulative currency value inside the vault equals Rs. 180, calculate the exact count of 50-paise coins.",
    "options": {
      "A": "120 coins",
      "B": "145 coins",
      "C": "100 coins",
      "D": "156 coins"
    },
    "correct_option": "A",
    "answer": "120 coins",
    "explanation": "Let coin counts be 2x, 3x, 4x.\nMonetary value = (2x × 1) + (3x × 0.50) + (4x × 0.25) = 2x + 1.5x + 1x = 4.5x.\n4.5x = 180 => x = 40.\nCount of 50-paise coins = 3x = 3 × 40 = 120 coins.",
    "difficulty": "Medium",
    "pattern": "Coin Bag Count vs Value Ratio Pattern",
    "companies": [
      "Cognizant",
      "Capgemini",
      "TCS"
    ],
