    "question": "Logical Deduction Challenge #1:\nStatements:\n1. Only a few routers are firewalls.\n2. All firewalls are switches.\nConclusions:\nI. Some routers are definitively not firewalls.\nII. All routers being switches is a distinct possibility.",
    "options": {
      "A": "Both Conclusion I and II follow",
      "B": "Only Conclusion I follows",
      "C": "Only Conclusion II follows",
      "D": "Neither Conclusion I nor II follows"
    },
